#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024
static char main_out[OUT_BUF_SIZE];

static void to_camel(const char *src) {
    size_t i = 0, j = 0;
    int capitalize = 0;
    while (src[i] != '\0' && j + 1 < OUT_BUF_SIZE) {
        char c = src[i];
        if (c == '_') {
            capitalize = 1;
        } else {
            if (capitalize && c >= 'a' && c <= 'z')
                c = (char)(c - 'a' + 'A');
            main_out[j++] = c;
            capitalize = 0;
        }
        ++i;
    }
    main_out[j] = '\0';
}

static void to_snake(const char *src) {
    size_t i = 0, j = 0;
    while (src[i] != '\0' && j + 1 < OUT_BUF_SIZE) {
        char c = src[i];
        if (c >= 'A' && c <= 'Z') {
            if (j != 0)
                main_out[j++] = '_';
            c = (char)(c - 'A' + 'a');
        }
        main_out[j++] = c;
        ++i;
    }
    main_out[j] = '\0';
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
    } else {
        puts("INVALID_MODE");
        return 0;
    }
    puts(main_out);
    return 0;
}
